ut{display:flex;align-items:center;gap:10px;padding:9px 12px;background:#081712cf;border:1px solid #ffffff2a;min-width:190px}.player-indicator{width:26px;height:26px;background:var(--lime);color:#172017;display:grid;place-items:center;font:800 14px 'Barlow Condensed';clip-path:polygon(20% 0,80% 0,100% 50%,80% 100%,20% 100%,0 50%)}.player-readout>div:nth-child(2) small,.player-readout>div:nth-child(2) strong{display:block}.player-readout>div:nth-child(2) small{font-size:7px;color:#b0bdb2;letter-spacing:1px}.player-readout>div:nth-child(2) strong{font:700 12px 'Barlow Condensed';letter-spacing:.8px;margin-top:3px}.stamina{height:3px;width:43px;background:#536059;margin-left:auto}.stamina span{height:100%;display:block;width:100%;background:var(--lime)}.stamina-label{font-size:7px;color:#abb9ac}.match-hint{font-size:8px;letter-spacing:1px;color:#e2ebe3;text-shadow:0 1px 5px #000}.match-hint i{color:var(--lime);padding:0 6px;font-style:normal}.match-stats{display:flex;gap:16px;background:#081712c9;padding:12px;border:1px solid #ffffff24;font-size:8px;color:#aab8ac;letter-spacing:1px}.match-stats b{color:#fff;margin-left:4px}.pause-panel{position:absolute;z-index:8;inset:0;display:grid;place-items:center;background:#020a08b8;backdrop-filter:blur(7px)}.pause-panel.hidden{display:none}.pause-card{text-align:center;padding:42px 50px;border:1px solid #ffffff2d;background:#0b1b15e8;box-shadow:0 25px 90px #0009}.pause-card h2{font:900 48px 'Barlow Condensed';margin:9px 0}.pause-card p{color:#aab8ac;font-size:12px;margin:0 0 24px}.pause-card .primary-cta{margin:auto;justify-content:center}.text-button{display:block;margin:18px auto 0;background:none;color:#b5c2b6;font-size:9px;letter-spacing:1.3px}.mobile-controls{display:none}.hidden{display:none!important}@keyframes rise{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}
