import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js';

const canvas=document.querySelector('#pitch');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
const scene=new THREE.Scene();scene.background=new THREE.Color(0x10251f);scene.fog=new THREE.Fog(0x10251f,100,230);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,350);camera.position.set(0,59,68);camera.lookAt(0,0,0);
scene.add(new THREE.HemisphereLight(0xcde3d5,0x243b2b,2.1));
const keyLight=new THREE.DirectionalLight(0xfff1cf,3.2);keyLight.position.set(-28,55,28);keyLight.castShadow=true;keyLight.shadow.mapSize.set(2048,2048);keyLight.shadow.camera.left=-75;keyLight.shadow.camera.right=75;keyLight.shadow.camera.top=55;keyLight.shadow.camera.bottom=-55;scene.add(keyLight);
const fill=new THREE.DirectionalLight(0x8cadff,1.15);fill.position.set(20,35,-40);scene.add(fill);
const mat=(color,rough=.8)=>new THREE.MeshStandardMaterial({color,roughness:rough});
const pitchMat=mat(0x1d603b);const field=new THREE.Mesh(new THREE.PlaneGeometry(108,72),pitchMat);field.rotation.x=-Math.PI/2;field.receiveShadow=true;field.position.y=-.12;scene.add(field);
// Alternating turf and stadium bowl
for(let i=0;i<9;i++){const stripe=new THREE.Mesh(new THREE.PlaneGeometry(12,68),mat(i%2?0x236b40:0x1d6038));stripe.rotation.x=-Math.PI/2;stripe.position.set(-48+i*12,-.105,0);stripe.receiveShadow=true;scene.add(stripe)}
const stadiumMat=mat(0x182823),tierMat=mat(0x273b32),railMat=mat(0x718274,.45);
function box(w,h,d,m,x,y,z){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;scene.add(o);return o}
// Bowl stands on all four sides
box(122,8,13,stadiumMat,0,5,-43);box(122,8,13,stadiumMat,0,5,43);box(13,8,86,stadiumMat,-60,5,0);box(13,8,86,stadiumMat,60,5,0);
for(let tier=0;tier<3;tier++){let yy=9+tier*5;box(121,1,16,tierMat,0,yy,-38-tier*3);box(121,1,16,tierMat,0,yy,38+tier*3);box(16,1,78,tierMat,-54-tier*3,yy,0);box(16,1,78,tierMat,54+tier*3,yy,0)}
// stadium fascia and illuminated roof trusses
box(124,.7,1.1,mat(0x93bd67),0,11,-29);box(124,.7,1.1,mat(0x93bd67),0,11,29);
for(let end of [-1,1]){for(let side of [-1,1]){let pole=box(1.2,21,1.2,mat(0x4b6054),end*68,10,side*34);let lamp=box(17,1.2,2,mat(0xf5f2d7),end*67,22,side*34);const pl=new THREE.PointLight(0xffefc6,90,90,2);pl.position.set(end*65,21,side*32);scene.add(pl)}}
// crowd seats: multi-colored tiny spectators instanced into tiers
const crowdGeo=new THREE.CapsuleGeometry(.12,.22,2,4);const crowdMats=[0x71826c,0xc3b99a,0x9c5541,0x496a84,0xd1d4b8,0x6a8a62,0x454d4a].map(c=>mat(c));
const crowds=crowdMats.map(m=>{const mesh=new THREE.InstancedMesh(crowdGeo,m,420);mesh.instanceMatrix.setUsage(THREE.StaticDrawUsage);mesh.castShadow=false;scene.add(mesh);return mesh});
let seed=1307;function rnd(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}
let crowdCount=0;for(let side=0;side<4;side++)for(let row=0;row<3;row++)for(let n=0;n<105;n++){const obj=new THREE.Object3D();let x,z;if(side<2){x=(rnd()-.5)*118;z=(side===0?-1:1)*(33+row*4+rnd()*3)}else{x=(side===2?-1:1)*(50+row*4+rnd()*3);z=(rnd()-.5)*67}obj.position.set(x,8+row*4+rnd()*2,z);obj.rotation.x=(rnd()-.5)*.24;obj.updateMatrix();crowds[crowdCount%crowds.length].setMatrixAt(Math.floor(crowdCount/crowds.length),obj.matrix);crowdCount++}
for(const c of crowds)c.instanceMatrix.needsUpdate=true;
// field markings
const lineMat=new THREE.MeshBasicMaterial({color:0xe6eee0,transparent:true,opacity:.77});function line(points){const g=new THREE.BufferGeometry().setFromPoints(points.map(p=>new THREE.Vector3(p[0],.025,p[1])));scene.add(new THREE.Line(g,lineMat))}function rect(x1,z1,x2,z2){line([[x1,z1],[x2,z1],[x2,z2],[x1,z2],[x1,z1]])}
rect(-52,-34,52,34);line([[0,-34],[0,34]]);const circlePts=[];for(let i=0;i<=80;i++){let a=i/80*Math.PI*2;circlePts.push([9.15*Math.cos(a),9.15*Math.sin(a)])}line(circlePts);rect(-52,-20,-35,20);rect(35,-20,52,20);rect(-52,-9,-44,9);rect(44,-9,52,9);
for(const s of [-1,1]){const goalMat=mat(0xe4e9dc,.45);for(const z of [-3.66,3.66])box(.25,2.4,.25,goalMat,s*52,1.2,z);box(.25,.25,7.3,goalMat,s*52,2.4,0);}
// Player model: stylized athletic 3D figures with articulated limbs and numbered shirts
const skinMats=[mat(0x9a6246),mat(0xd0a17b),mat(0x744632),mat(0xe0b68e)];
function makePlayer(team,index){const g=new THREE.Group();const home=team===0;const shirt=mat(home?(index===0?0xd4e8a4:0x263e34):(index===0?0xe9e9dc:0x485c73),.52),short=mat(home?0x1a2921:0xdddccf,.7),sock=mat(home?0xc2df8a:0x283c50),skin=skinMats[(index+team*2)%skinMats.length];
const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.62,.85,4,8),shirt);torso.position.y=1.62;torso.castShadow=true;g.add(torso);const shorts=new THREE.Mesh(new THREE.CylinderGeometry(.43,.48,.48,8),short);shorts.position.y=.92;g.add(shorts);
const head=new THREE.Mesh(new THREE.SphereGeometry(.31,12,10),skin);head.position.y=2.55;head.castShadow=true;g.add(head);const hair=new THREE.Mesh(new THREE.SphereGeometry(.32,10,6,0,Math.PI*2,0,Math.PI*.48),mat(index%2?0x281e17:0x41332a));hair.position.y=2.63;g.add(hair);
const arms=[],legs=[];for(let side of [-1,1]){const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.13,.62,3,6),shirt);arm.position.set(side*.68,1.68,0);arm.rotation.z=side*-.14;arm.castShadow=true;g.add(arm);arms.push(arm);const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.16,.66,3,6),sock);leg.position.set(side*.25,.49,0);leg.castShadow=true;g.add(leg);legs.push(leg)}
const number=new THREE.Mesh(new THREE.PlaneGeometry(.38,.4),new THREE.MeshBasicMaterial({color:home?0xd4e8a4:0x24372c}));number.position.set(0,1.69,.624);g.add(number);
const shadow=new THREE.Mesh(new THREE.CircleGeometry(.8,20),new THREE.MeshBasicMaterial({color:0x07130d,transparent:true,opacity:.25}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.03;g.add(shadow);
scene.add(g);return {group:g,legs,arms,team,index,vx:0,vz:0,stamina:100,pace:5.2+rnd()*1.4,phase:rnd()*6,homeX:0,homeZ:0}}
const teams=[[],[]];let ball,ballVel=new THREE.Vector3(),controlled=0,score=[0,0],shots=0,matchActive=false,paused=false,elapsed=0,stamina=100,last=performance.now(),kickCooldown=0,eventTimeout=0,weather='CLEAR';
const clubNames=['MERIDIAN FC','ATHLETIC CLUB'];const shortNames=['MER','ATH'];
for(let t=0;t<2;t++)for(let i=0;i<6;i++)teams[t].push(makePlayer(t,i));
function resetPositions(){for(let t=0;t<2;t++)for(let i=0;i<6;i++){let p=teams[t][i];let x=(i===0?0:(i%3)*10-10)*(t===0?1:-1);let z=(i===0?0:((i<3?-1:1)*(8+Math.floor(i/3)*8)));if(t===1)x*=-1;p.group.position.set(x,0,z);p.homeX=x;p.homeZ=z;p.vx=p.vz=0}controlled=0;teams[0][0].group.position.set(-5,0,0);ball.position.set(0,.35,0);ballVel.set(0,0,0)}
const ballMesh=new THREE.Mesh(new THREE.SphereGeometry(.38,20,16),mat(0xf4f2dc,.3));ballMesh.castShadow=true;ballMesh.position.set(0,.38,0);scene.add(ballMesh);ball=ballMesh;const ballMark=new THREE.Mesh(new THREE.CircleGeometry(.53,24),new THREE.MeshBasicMaterial({color:0x07130d,transparent:true,opacity:.22}));ballMark.rotation.x=-Math.PI/2;ballMark.position.y=.02;scene.add(ballMark);
