resetPositions();
const menuScreen=document.querySelector('#menuScreen'),matchScreen=document.querySelector('#matchScreen'),homeScore=document.querySelector('#homeScore'),awayScore=document.querySelector('#awayScore'),clockEl=document.querySelector('#clock');
function notify(text){const e=document.querySelector('#matchEvent');e.innerHTML=`<span>✦</span> ${text} <span>✦</span>`;e.style.opacity='1';clearTimeout(eventTimeout);eventTimeout=setTimeout(()=>e.style.opacity='0',2100)}
function startMatch(){menuScreen.classList.add('hidden');matchScreen.classList.remove('hidden');matchActive=true;paused=false;elapsed=0;score=[0,0];shots=0;homeScore.textContent='0';awayScore.textContent='0';document.querySelector('#shots').textContent='0';resetPositions();notify('KICK OFF');audioTone(620,.12,'sine',.04)}
document.querySelector('#playNow').addEventListener('click',startMatch);document.querySelector('#backMenu').addEventListener('click',()=>{matchActive=false;matchScreen.classList.add('hidden');menuScreen.classList.remove('hidden');document.querySelector('#pausePanel').classList.add('hidden')});
function togglePause(){if(!matchActive)return;paused=!paused;document.querySelector('#pausePanel').classList.toggle('hidden',!paused)}document.querySelector('#pauseBtn').addEventListener('click',togglePause);document.querySelector('#resumeBtn').addEventListener('click',togglePause);document.querySelector('#quitMatch').addEventListener('click',()=>document.querySelector('#backMenu').click());
// Lightweight generated match sounds; no external audio assets.
let audioCtx;function audioTone(freq,duration,type='sine',volume=.025){try{audioCtx??=new AudioContext();let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch{}}
const keys={};window.addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(e.key.toLowerCase()))e.preventDefault();if(e.key==='Escape')togglePause();if(e.key.toLowerCase()==='f')shoot();if(e.key===' ')pass(false);if(e.key.toLowerCase()==='g')pass(true);if(e.key.toLowerCase()==='e')switchPlayer();if(e.key.toLowerCase()==='q')tackle();if(e.key.toLowerCase()==='c')skill()});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
let joy={x:0,z:0},joystick=document.querySelector('#joystick'),knob=joystick.querySelector('.joy-knob');let joyPointer=null;joystick.addEventListener('pointerdown',e=>{joyPointer=e.pointerId;joystick.setPointerCapture(joyPointer);moveJoy(e)});joystick.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)moveJoy(e)});function moveJoy(e){let r=joystick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),d=Math.hypot(dx,dy),max=39;if(d>max){dx*=max/d;dy*=max/d}joy.x=dx/max;joy.z=dy/max;knob.style.left=`calc(50% + ${dx}px)`;knob.style.top=`calc(50% + ${dy}px)`}function endJoy(){joyPointer=null;joy.x=joy.z=0;knob.style.left='50%';knob.style.top='50%'}joystick.addEventListener('pointerup',endJoy);joystick.addEventListener('pointercancel',endJoy);
document.querySelectorAll('[data-action]').forEach(b=>{const action=b.dataset.action;b.addEventListener('pointerdown',e=>{e.preventDefault();if(action==='shoot')shoot();if(action==='pass')pass(false);if(action==='through')pass(true);if(action==='switch')switchPlayer();if(action==='tackle')tackle();if(action==='skill')skill();if(action==='sprint')keys.shift=true});['pointerup','pointerleave','pointercancel'].forEach(ev=>b.addEventListener(ev,()=>{if(action==='sprint')keys.shift=false}))});
function nearest(team,from){let best=null,dist=Infinity;for(const p of teams[team]){if(p===from)continue;let d=p.group.position.distanceTo(ball.position);if(d<dist){best=p;dist=d}}return best}
function switchPlayer(){let next=nearest(0,teams[0][controlled]);if(next)controlled=next.index;document.querySelector('.player-indicator').textContent=String(controlled+7)}
function kick(power,loft=2.4){const p=teams[0][controlled],dir=new THREE.Vector3(1,0,0);if(Math.abs(keys.w||keys.arrowup||joy.z)<.01&&Math.abs(keys.s||keys.arrowdown||joy.z)<.01){let target=nearest(0,p);if(target)dir.set(target.group.position.x-p.group.position.x,0,target.group.position.z-p.group.position.z).normalize()}else dir.z=Number(keys.s||keys.arrowdown)?1:-1;ballVel.set(dir.x*power,loft,dir.z*power);kickCooldown=.36;audioTone(105,.09,'triangle',.08)}
function shoot(){if(!matchActive||paused)return;const p=teams[0][controlled];if(p.group.position.distanceTo(ball.position)<2.8){kick(17+((keys.shift)?3:0),3.7);shots++;document.querySelector('#shots').textContent=shots;notify('HIT IT!')}}
function pass(through){if(!matchActive||paused)return;const p=teams[0][controlled],mate=nearest(0,p);if(p.group.position.distanceTo(ball.position)<2.8&&mate){let d=mate.group.position.clone().sub(p.group.position);if(through)d.x+=8;d.y=0;d.normalize();ballVel.set(d.x*(through?12:9),through?2.8:1.3,d.z*(through?12:9));kickCooldown=.32;audioTone(190,.08,'triangle',.045)}}
function tackle(){let p=teams[0][controlled],enemy=teams[1].slice().sort((a,b)=>a.group.position.distanceTo(p.group.position)-b.group.position.distanceTo(p.group.position))[0];if(enemy&&enemy.group.position.distanceTo(p.group.position)<3.2){if(ball.position.distanceTo(enemy.group.position)<3.4){ballVel.set(-5+Math.random()*2,1.2,(Math.random()-.5)*5);notify('CLEAN TACKLE');audioTone(95,.14,'sawtooth',.035)}}}
function skill(){let p=teams[0][controlled];p.vx+=p.group.rotation.y<0?2:-2;p.vz+=(Math.random()-.5)*6;audioTone(360,.07,'sine',.018)}
function moveToward(p,target,dt,speed){let dx=target.x-p.group.position.x,dz=target.z-p.group.position.z,d=Math.hypot(dx,dz);if(d>.12){let v=Math.min(speed,d*3);p.vx+=(dx/d*v-p.vx)*Math.min(1,dt*4);p.vz+=(dz/d*v-p.vz)*Math.min(1,dt*4);p.group.rotation.y=Math.atan2(dx,dz)}}
function scoreGoal(team){score[team]++;(team===0?homeScore:awayScore).textContent=String(score[team]);notify(team===0?'GOAL! WHAT A FINISH':'GOAL — ATHLETIC CLUB');audioTone(780,.5,'sine',.08);setTimeout(()=>audioTone(1040,.6,'sine',.06),180);resetPositions();elapsed+=8}
function updateGame(dt){if(!matchActive||paused)return;elapsed+=dt*12;let secs=Math.floor(elapsed);clockEl.textContent=`${String(Math.floor(secs/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`;if(elapsed>360){matchActive=false;notify('FULL TIME');setTimeout(()=>togglePause(),400)}kickCooldown=Math.max(0,kickCooldown-dt);const user=teams[0][controlled];let mx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joy.x,mz=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joy.z;let ml=Math.hypot(mx,mz);if(ml>1){mx/=ml;mz/=ml}let sprint=!!keys.shift&&user.stamina>4;let speed=(sprint?10:7.2)*(user.stamina<25?.76:1);user.vx+=(mx*speed-user.vx)*Math.min(1,dt*10);user.vz+=(mz*speed-user.vz)*Math.min(1,dt*10);if(ml>.08){user.group.rotation.y=Math.atan2(mx,mz);user.stamina=Math.max(0,user.stamina-(sprint?13:1.3)*dt)}else user.stamina=Math.min(100,user.stamina+5*dt);document.querySelector('#staminaFill').style.width=`${user.stamina}%`;
// intelligent supporting runs, pressing and possession
let carrierTeam=-1,carrier=null,minDist=3.1;for(let t=0;t<2;t++)for(const p of teams[t]){let d=p.group.position.distanceTo(ball.position);if(d<minDist&&ball.position.y<2){carrierTeam=t;carrier=p;minDist=d}}
for(let t=0;t<2;t++)for(const p of teams[t]){if(t===0&&p===user)continue;let target=new THREE.Vector3(p.homeX,p.group.position.y,p.homeZ);if(t===0){if(carrierTeam===0){target.set(Math.min(43,p.homeX+14),0,p.homeZ+(p.index%2?6:-6))}else if(p===nearest(0,null)){target.copy(ball.position);target.x=Math.min(45,target.x)}}else{if(carrierTeam===1&&carrier===p){target.set(Math.max(-48,p.group.position.x-30),0,p.group.position.z*.55)}else if(carrierTeam===0){target.copy(ball.position);target.x-=1}else if(p===nearest(1,null)){target.copy(ball.position)}}moveToward(p,target,dt,p.pace);}
for(let t=0;t<2;t++)for(const p of teams[t]){let pos=p.group.position;pos.x+=p.vx*dt;pos.z+=p.vz*dt;pos.x=Math.max(-50,Math.min(50,pos.x));pos.z=Math.max(-32,Math.min(32,pos.z));p.vx*=Math.exp(-2.2*dt);p.vz*=Math.exp(-2.2*dt);p.phase+=dt*(4+Math.hypot(p.vx,p.vz));let run=Math.min(1,Math.hypot(p.vx,p.vz)/3);p.legs[0].rotation.x=Math.sin(p.phase)*.65*run;p.legs[1].rotation.x=-Math.sin(p.phase)*.65*run;p.arms[0].rotation.x=-Math.sin(p.phase)*.4*run;p.arms[1].rotation.x=Math.sin(p.phase)*.4*run;p.group.position.y=Math.abs(Math.sin(p.phase*2))*.08*run}
// ball possession, pass interceptions, rolling friction, bounces
if(carrierTeam===1&&carrier&&Math.random()<dt*.55&&carrier.group.position.x<-27){let aim=new THREE.Vector3(-53,.4,(Math.random()-.5)*9).sub(ball.position).normalize();ballVel.set(aim.x*15,3,aim.z*15);audioTone(100,.1,'triangle',.05)}
ball.position.addScaledVector(ballVel,dt);ballVel.x*=Math.exp(-.32*dt);ballVel.z*=Math.exp(-.32*dt);ballVel.y-=9.8*dt;if(ball.position.y<.38){ball.position.y=.38;if(ballVel.y<-.7)ballVel.y*=-.48;else ballVel.y=0;ballVel.x*=.975;ballVel.z*=.975}ball.rotation.x+=ballVel.z*dt;ball.rotation.z-=ballVel.x*dt;
// close control gently brings ball forward, contested players can win it
if(carrierTeam===0&&carrier===user&&kickCooldown<=0){let forward=new THREE.Vector3(Math.sin(user.group.rotation.y),0,Math.cos(user.group.rotation.y));let target=user.group.position.clone().add(forward.multiplyScalar(1.35));ball.position.x+=(target.x-ball.position.x)*Math.min(1,dt*5);ball.position.z+=(target.z-ball.position.z)*Math.min(1,dt*5);ball.position.y=Math.max(.38,ball.position.y)}
if(Math.abs(ball.position.z)>34){ball.position.z=Math.sign(ball.position.z)*33.7;ballVel.z*=-.65}if(ball.position.x>52&&Math.abs(ball.position.z)<3.8)scoreGoal(0);else if(ball.position.x<-52&&Math.abs(ball.position.z)<3.8)scoreGoal(1);else if(Math.abs(ball.position.x)>53){ballVel.x*=-.7;ball.position.x=Math.sign(ball.position.x)*52.5}
ballMark.position.x=ball.position.x;ballMark.position.z=ball.position.z;document.querySelector('#possession').textContent=carrierTeam===0?'56':'44';let camTarget=new THREE.Vector3(ball.position.x*.25,0,ball.position.z*.22);camera.position.x+=(camTarget.x-camera.position.x)*dt*.4;camera.position.z+=(68-camera.position.z)*dt*.3;camera.lookAt(camTarget);
}
// Menu utility panels: clubs, career, training and settings are functional prototype screens.
const panel=document.querySelector('#utilityPanel');let selectedHome='MERIDIAN FC',selectedAway='ATHLETIC CLUB';function showPanel(type){if(type==='home'){panel.classList.add('hidden');return}panel.classList.remove('hidden');if(type==='clubs')panel.innerHTML='<h2>CHOOSE YOUR COLORS</h2><p>Select a side for your next fixture. Every club has its own identity and match kit.</p><div class="club-chips">'+['Meridian FC','Athletic Club','Real Madrid','Barcelona','Man City','Liverpool','Bayern','Paris SG','Arsenal','Juventus'].map((n,i)=>`<button class="club-chip ${i<2?'selected':''}" data-club="${n}">${n}</button>`).join('')+'</div>';if(type==='career')panel.innerHTML='<h2>YOUR STORY STARTS HERE</h2><p>Build a club from the ground up. Shape your squad, find your formation and chase the silverware. Career mode is coming to the next season update.</p><button class="formation-chip selected">CONTINUE AS MERIDIAN FC　↗</button>';if(type==='training')panel.innerHTML='<h2>TRAINING GROUND</h2><p>Practice the essentials before kickoff. Use <b>WASD</b> to move, <b>F</b> to shoot, <b>SPACE</b> to pass, <b>SHIFT</b> to sprint and <b>E</b> to switch player.</p><div class="club-chips"><button class="formation-chip selected">FREE PRACTICE</button><button class="formation-chip">FINISHING</button><button class="formation-chip">PASSING</button></div>';if(type==='settings')panel.innerHTML='<h2>MATCH SETTINGS</h2><p>Set the scene for your next match.</p><div class="club-chips"><button class="formation-chip selected" data-weather="CLEAR">☀ CLEAR</button><button class="formation-chip" data-weather="CLOUDY">☁ CLOUDY</button><button class="formation-chip" data-weather="RAIN">☂ RAIN</button><button class="formation-chip" data-weather="DAY">DAYLIGHT</button><button class="formation-chip" data-weather="NIGHT">NIGHT</button></div><p style="margin-top:13px;font-size:10px">FORMATION　 <button class="formation-chip selected">4-3-3</button> <button class="formation-chip">4-4-2</button> <button class="formation-chip">4-2-3-1</button></p>';panel.querySelectorAll('[data-club]').forEach(b=>b.onclick=()=>{panel.querySelectorAll('[data-club]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');selectedHome=b.dataset.club});panel.querySelectorAll('[data-weather]').forEach(b=>b.onclick=()=>{weather=b.dataset.weather;panel.querySelectorAll('[data-weather]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');applyWeather()})}
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.nav-item').forEach(x=>x.classList.remove('active'));b.classList.add('active');showPanel(b.dataset.panel)}));function applyWeather(){if(weather==='NIGHT'){scene.background.set(0x07101d);scene.fog.color.set(0x07101d);keyLight.intensity=1.2;fill.intensity=1.5}else if(weather==='CLOUDY'){scene.background.set(0x53656a);scene.fog.color.set(0x53656a);keyLight.intensity=1.5}else if(weather==='DAY'){scene.background.set(0x7294a0);scene.fog.color.set(0x7294a0);keyLight.intensity=3.8}else{scene.background.set(0x10251f);scene.fog.color.set(0x10251f);keyLight.intensity=3.2}}
